import SwiftUI
struct NotificationItem: Identifiable { let id = UUID(); let title: String; let message: String; let symbol: String; let tint: Color; let time: String; var isRead: Bool }
struct NotificationsView: View {
    @Environment(\.dismiss) private var dismiss; @AppStorage("notificationsEnabled") private var notificationsEnabled = true
    @State private var notifications: [NotificationItem] = [NotificationItem(title: "Transferencia recibida", message: "Recibiste S/ 450.00 de María López", symbol: "arrow.down.circle.fill", tint: BBVA.success, time: "Hace 5 min", isRead: false), NotificationItem(title: "Pago de servicio", message: "Se debitó S/ 89.90 por Luz del Sur", symbol: "bolt.fill", tint: BBVA.midBlue, time: "Hace 2 horas", isRead: false), NotificationItem(title: "Cashback disponible", message: "Tienes S/ 23.50 por cobrar", symbol: "gift.fill", tint: BBVA.aqua, time: "Ayer", isRead: true), NotificationItem(title: "Meta de ahorro", message: "Completaste el 80% de tu meta", symbol: "flag.checkered", tint: BBVA.coreBlue, time: "Ayer", isRead: true), NotificationItem(title: "Seguro activado", message: "Tu seguro está activo hasta Nov 2027", symbol: "shield.checkered", tint: Color(hex: 0x0E9AA0), time: "Hace 3 días", isRead: true)]
    private var unreadCount: Int { notifications.filter { !$0.isRead }.count }
    var body: some View {
        ZStack { BBVA.navy.ignoresSafeArea(edges: .top); BBVA.sand.ignoresSafeArea(edges: .bottom); VStack(spacing: 0) { VStack(alignment: .leading, spacing: 16) { HStack { Button { Haptics.tap(); dismiss() } label: { Image(systemName: "chevron.left").font(.system(size: 16, weight: .bold)).foregroundColor(.white).frame(width: 38, height: 38).background(Circle().fill(Color.white.opacity(0.14))) }; Spacer(); Text("Notificaciones").font(BBVAFont.title(20)).foregroundColor(.white); Spacer(); Button { Haptics.tap(); notificationsEnabled.toggle() } label: { Image(systemName: notificationsEnabled ? "bell.fill" : "bell.slash.fill").font(.system(size: 16, weight: .semibold)).foregroundColor(notificationsEnabled ? BBVA.aqua : BBVA.slate).frame(width: 38, height: 38).background(Circle().fill(Color.white.opacity(0.14))) } }.padding(.top, Inset.top + 8); HStack { Text("\(unreadCount) nuevas").font(BBVAFont.body(14, .medium)).foregroundColor(.white.opacity(0.7)); Spacer(); if unreadCount > 0 { Button("Marcar todas como leídas") { withAnimation { for i in notifications.indices { notifications[i].isRead = true } }; Haptics.success() }.font(BBVAFont.body(13, .demi)).foregroundColor(BBVA.aqua) } } }.padding(.horizontal, 20).padding(.bottom, 20).background(BBVA.navy); ScrollView { VStack(spacing: 0) { if !notificationsEnabled { VStack(spacing: 12) { Image(systemName: "bell.slash").font(.system(size: 40, weight: .light)).foregroundColor(BBVA.slate); Text("Notificaciones desactivadas").font(BBVAFont.title(18)).foregroundColor(BBVA.navy); Text("Actívalas para recibir alertas").font(BBVAFont.body(14)).foregroundColor(BBVA.slate).multilineTextAlignment(.center); Button { withAnimation(.spring(response: 0.4)) { notificationsEnabled = true }; Haptics.success() } label: { Text("Activar notificaciones").font(BBVAFont.body(15, .demi)).foregroundColor(.white).padding(.horizontal, 20).padding(.vertical, 12).background(Capsule().fill(BBVA.coreBlue)) }.padding(.top, 8) }.padding(40).frame(maxWidth: .infinity) } else if notifications.isEmpty { VStack(spacing: 12) { Image(systemName: "bell").font(.system(size: 40, weight: .light)).foregroundColor(BBVA.slate); Text("Sin notificaciones").font(BBVAFont.title(18)).foregroundColor(BBVA.navy) }.padding(40).frame(maxWidth: .infinity) } else { ForEach(notifications) { n in NotificationRow(item: n) { if !n.isRead { if let idx = notifications.firstIndex(where: { $0.id == n.id }) { withAnimation { notifications[idx].isRead = true } } } } } } }.padding(.horizontal, 20).padding(.vertical, 20).frame(maxWidth: .infinity).background(UnevenRoundedRectangle(topLeadingRadius: 32, topTrailingRadius: 32).fill(BBVA.sand).ignoresSafeArea(edges: .bottom)) }.scrollIndicators(.hidden) } }
    }
}
struct NotificationRow: View { let item: NotificationItem; let onTap: () -> Void; var body: some View { Button(action: onTap) { HStack(alignment: .top, spacing: 14) { ZStack { Circle().fill(item.tint.opacity(0.12)); Image(systemName: item.symbol).font(.system(size: 18, weight: .semibold)).foregroundColor(item.tint) }.frame(width: 44, height: 44); VStack(alignment: .leading, spacing: 4) { HStack { Text(item.title).font(BBVAFont.body(15, item.isRead ? .regular : .demi)).foregroundColor(BBVA.navy); Spacer(); if !item.isRead { Circle().fill(BBVA.aqua).frame(width: 8, height: 8) } }; Text(item.message).font(BBVAFont.body(13)).foregroundColor(BBVA.slate).lineLimit(2); Text(item.time).font(BBVAFont.body(11, .medium)).foregroundColor(BBVA.line).padding(.top, 2) } }.padding(.vertical, 14).padding(.horizontal, 16).background(RoundedRectangle(cornerRadius: 16, style: .continuous).fill(item.isRead ? Color.white : BBVA.serene.opacity(0.4))).padding(.bottom, 10) } } }
